import{_ as a,c as s,o as i,ag as t}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Questions fréquentes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/faq.md","filePath":"fr/guide/faq.md","lastUpdated":1794112334000}'),n={name:"fr/guide/faq.md"};function o(r,e,l,u,c,d){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="questions-frequentes" tabindex="-1">Questions fréquentes <a class="header-anchor" href="#questions-frequentes" aria-label="Permalink to &quot;Questions fréquentes&quot;">​</a></h1><h2 id="questions-generales" tabindex="-1">Questions générales <a class="header-anchor" href="#questions-generales" aria-label="Permalink to &quot;Questions générales&quot;">​</a></h2><h3 id="qu-est-ce-que-nicasa" tabindex="-1">Qu&#39;est-ce que Nicasa ? <a class="header-anchor" href="#qu-est-ce-que-nicasa" aria-label="Permalink to &quot;Qu&#39;est-ce que Nicasa ?&quot;">​</a></h3><p>Nicasa est une visionneuse d&#39;images de bureau moderne et un outil de capture d&#39;écran conçu exclusivement pour macOS. Il offre une navigation rapide et intuitive dans vos collections d&#39;images, avec une interface claire et réactive, ainsi que de puissantes capacités d&#39;édition par IA.</p><h3 id="nicasa-est-il-gratuit" tabindex="-1">Nicasa est-il gratuit ? <a class="header-anchor" href="#nicasa-est-il-gratuit" aria-label="Permalink to &quot;Nicasa est-il gratuit ?&quot;">​</a></h3><p>L&#39;extension Chrome est entièrement gratuite. L&#39;application macOS nécessite un achat unique de 4,99 $ pour accéder à toutes les fonctionnalités.</p><h3 id="quels-systemes-d-exploitation-sont-pris-en-charge" tabindex="-1">Quels systèmes d&#39;exploitation sont pris en charge ? <a class="header-anchor" href="#quels-systemes-d-exploitation-sont-pris-en-charge" aria-label="Permalink to &quot;Quels systèmes d&#39;exploitation sont pris en charge ?&quot;">​</a></h3><p>Nicasa est actuellement disponible exclusivement pour macOS 10.13 ou version ultérieure. Les versions Windows et Linux ne sont pas disponibles pour le moment.</p><h3 id="comment-mettre-a-jour-nicasa" tabindex="-1">Comment mettre à jour Nicasa ? <a class="header-anchor" href="#comment-mettre-a-jour-nicasa" aria-label="Permalink to &quot;Comment mettre à jour Nicasa ?&quot;">​</a></h3><p>Les mises à jour passent par le Mac App Store. Vous serez notifié lorsque des mises à jour sont disponibles et pourrez les installer directement depuis l&#39;application App Store.</p><h2 id="questions-d-utilisation" tabindex="-1">Questions d&#39;utilisation <a class="header-anchor" href="#questions-d-utilisation" aria-label="Permalink to &quot;Questions d&#39;utilisation&quot;">​</a></h2><h3 id="comment-prendre-des-captures-d-ecran-avec-nicasa" tabindex="-1">Comment prendre des captures d&#39;écran avec Nicasa ? <a class="header-anchor" href="#comment-prendre-des-captures-d-ecran-avec-nicasa" aria-label="Permalink to &quot;Comment prendre des captures d&#39;écran avec Nicasa ?&quot;">​</a></h3><ol><li>Lancez Nicasa</li><li>Cliquez sur le bouton de capture dans la barre d&#39;outils ou utilisez <code>Cmd+S</code></li><li>Sélectionnez la zone à capturer</li><li>La capture s&#39;ouvre dans Nicasa pour une édition immédiate</li></ol><h3 id="nicasa-fonctionne-t-il-avec-les-images-web" tabindex="-1">Nicasa fonctionne-t-il avec les images web ? <a class="header-anchor" href="#nicasa-fonctionne-t-il-avec-les-images-web" aria-label="Permalink to &quot;Nicasa fonctionne-t-il avec les images web ?&quot;">​</a></h3><p>Oui ! Installez l&#39;extension Chrome gratuite de Nicasa pour :</p><ul><li>voir toutes les images de n&#39;importe quel site web au même endroit</li><li>extraire et parcourir les images instantanément</li><li>ouvrir les images directement dans Nicasa pour une meilleure visualisation</li></ul><h3 id="quelles-fonctionnalites-d-edition-par-ia-sont-disponibles" tabindex="-1">Quelles fonctionnalités d&#39;édition par IA sont disponibles ? <a class="header-anchor" href="#quelles-fonctionnalites-d-edition-par-ia-sont-disponibles" aria-label="Permalink to &quot;Quelles fonctionnalités d&#39;édition par IA sont disponibles ?&quot;">​</a></h3><p>Nicasa inclut de puissants outils d&#39;IA :</p><ul><li><strong>Amélioration automatique</strong> : améliore automatiquement la qualité de l&#39;image</li><li><strong>Recadrage intelligent</strong> : suggestions intelligentes de recadrage</li><li><strong>Retouche</strong> : supprime intelligemment les objets indésirables</li><li><strong>Correction des couleurs</strong> : ajustements de couleur pilotés par l&#39;IA</li><li><strong>Réduction du bruit</strong> : élimine le bruit et le grain</li></ul><h3 id="comment-fonctionne-le-mode-superposition-transparente" tabindex="-1">Comment fonctionne le mode superposition transparente ? <a class="header-anchor" href="#comment-fonctionne-le-mode-superposition-transparente" aria-label="Permalink to &quot;Comment fonctionne le mode superposition transparente ?&quot;">​</a></h3><p>Parfait pour les designers et les artistes :</p><ul><li>épinglez des images au-dessus de toutes les fenêtres avec une transparence réglable</li><li>utilisez-le pour le décalquage, le travail de référence ou la comparaison d&#39;interfaces</li><li>conserve sa position dans toutes les applications</li></ul><h2 id="questions-techniques" tabindex="-1">Questions techniques <a class="header-anchor" href="#questions-techniques" aria-label="Permalink to &quot;Questions techniques&quot;">​</a></h2><h3 id="pourquoi-dois-je-accorder-l-autorisation-d-enregistrement-de-l-ecran" tabindex="-1">Pourquoi dois-je accorder l&#39;autorisation d&#39;enregistrement de l&#39;écran ? <a class="header-anchor" href="#pourquoi-dois-je-accorder-l-autorisation-d-enregistrement-de-l-ecran" aria-label="Permalink to &quot;Pourquoi dois-je accorder l&#39;autorisation d&#39;enregistrement de l&#39;écran ?&quot;">​</a></h3><p>L&#39;autorisation d&#39;enregistrement de l&#39;écran est nécessaire pour la fonction de capture. Elle permet à Nicasa de capturer votre écran lorsque vous utilisez l&#39;outil de capture.</p><h3 id="puis-je-utiliser-nicasa-hors-ligne" tabindex="-1">Puis-je utiliser Nicasa hors ligne ? <a class="header-anchor" href="#puis-je-utiliser-nicasa-hors-ligne" aria-label="Permalink to &quot;Puis-je utiliser Nicasa hors ligne ?&quot;">​</a></h3><p>Oui. L&#39;application macOS fonctionne entièrement hors ligne pour les fichiers image locaux. L&#39;extraction d&#39;images web via l&#39;extension Chrome nécessite une connexion internet.</p><h3 id="quelles-versions-de-macos-sont-prises-en-charge" tabindex="-1">Quelles versions de macOS sont prises en charge ? <a class="header-anchor" href="#quelles-versions-de-macos-sont-prises-en-charge" aria-label="Permalink to &quot;Quelles versions de macOS sont prises en charge ?&quot;">​</a></h3><p>Nicasa prend en charge macOS 10.13 ou version ultérieure. Il est optimisé pour Apple Silicon et s&#39;exécute nativement sur les puces de la série M.</p><h3 id="quelles-autorisations-l-extension-chrome-demande-t-elle" tabindex="-1">Quelles autorisations l&#39;extension Chrome demande-t-elle ? <a class="header-anchor" href="#quelles-autorisations-l-extension-chrome-demande-t-elle" aria-label="Permalink to &quot;Quelles autorisations l&#39;extension Chrome demande-t-elle ?&quot;">​</a></h3><p>L&#39;extension demande l&#39;accès au contenu des pages uniquement pour extraire les URL des images. Aucun historique de navigation n&#39;est lu ni stocké.</p><h3 id="mes-donnees-sont-elles-envoyees-quelque-part" tabindex="-1">Mes données sont-elles envoyées quelque part ? <a class="header-anchor" href="#mes-donnees-sont-elles-envoyees-quelque-part" aria-label="Permalink to &quot;Mes données sont-elles envoyées quelque part ?&quot;">​</a></h3><p>Non. Tout le traitement se fait localement sur votre appareil. Nicasa ne collecte, ne transmet ni ne stocke vos images.</p><h3 id="comment-sauvegarder-mes-reglages" tabindex="-1">Comment sauvegarder mes réglages ? <a class="header-anchor" href="#comment-sauvegarder-mes-reglages" aria-label="Permalink to &quot;Comment sauvegarder mes réglages ?&quot;">​</a></h3><p>Vos réglages sont stockés localement. Pour les sauvegarder :</p><ol><li>Allez dans Nicasa &gt; Préférences</li><li>Exportez vos réglages si l&#39;option est disponible</li><li>Ou sauvegardez manuellement le dossier des préférences de l&#39;application</li></ol><p>Les réglages sont stockés dans le dossier de données de l&#39;application. Copiez ce dossier pour sauvegarder vos préférences.</p><h3 id="existe-t-il-une-version-portable" tabindex="-1">Existe-t-il une version portable ? <a class="header-anchor" href="#existe-t-il-une-version-portable" aria-label="Permalink to &quot;Existe-t-il une version portable ?&quot;">​</a></h3><p>Une version portable est disponible pour Windows. Téléchargez-la depuis notre site web.</p><h2 id="questions-de-developpement" tabindex="-1">Questions de développement <a class="header-anchor" href="#questions-de-developpement" aria-label="Permalink to &quot;Questions de développement&quot;">​</a></h2><h3 id="puis-je-contribuer-a-nicasa" tabindex="-1">Puis-je contribuer à Nicasa ? <a class="header-anchor" href="#puis-je-contribuer-a-nicasa" aria-label="Permalink to &quot;Puis-je contribuer à Nicasa ?&quot;">​</a></h3><p>Rendez-vous sur notre <a href="https://github.com/nicasa-project/nicasa-support" target="_blank" rel="noreferrer">dépôt GitHub</a> pour contribuer au code, signaler des problèmes ou proposer des fonctionnalités.</p><h3 id="comment-compiler-nicasa-depuis-les-sources" tabindex="-1">Comment compiler Nicasa depuis les sources ? <a class="header-anchor" href="#comment-compiler-nicasa-depuis-les-sources" aria-label="Permalink to &quot;Comment compiler Nicasa depuis les sources ?&quot;">​</a></h3><p>Consultez notre documentation développeur sur GitHub pour les instructions de compilation.</p><h3 id="quelles-technologies-nicasa-utilise-t-il" tabindex="-1">Quelles technologies Nicasa utilise-t-il ? <a class="header-anchor" href="#quelles-technologies-nicasa-utilise-t-il" aria-label="Permalink to &quot;Quelles technologies Nicasa utilise-t-il ?&quot;">​</a></h3><p>Nicasa est construit avec des technologies web modernes, dont Electron pour l&#39;enveloppe de bureau et Vue.js pour l&#39;interface.</p><h2 id="questions-de-confidentialite" tabindex="-1">Questions de confidentialité <a class="header-anchor" href="#questions-de-confidentialite" aria-label="Permalink to &quot;Questions de confidentialité&quot;">​</a></h2><h3 id="nicasa-collecte-t-il-des-donnees" tabindex="-1">Nicasa collecte-t-il des données ? <a class="header-anchor" href="#nicasa-collecte-t-il-des-donnees" aria-label="Permalink to &quot;Nicasa collecte-t-il des données ?&quot;">​</a></h3><p>Non, Nicasa ne collecte ni ne transmet aucune donnée personnelle. Tout le traitement des images se fait localement sur votre appareil.</p><h3 id="mes-images-sont-elles-en-securite" tabindex="-1">Mes images sont-elles en sécurité ? <a class="header-anchor" href="#mes-images-sont-elles-en-securite" aria-label="Permalink to &quot;Mes images sont-elles en sécurité ?&quot;">​</a></h3><p>Oui. Nicasa n&#39;accède qu&#39;aux images que vous ouvrez explicitement. Il ne téléverse ni ne partage vos fichiers.</p><h3 id="quelles-autorisations-nicasa-necessite-t-il" tabindex="-1">Quelles autorisations Nicasa nécessite-t-il ? <a class="header-anchor" href="#quelles-autorisations-nicasa-necessite-t-il" aria-label="Permalink to &quot;Quelles autorisations Nicasa nécessite-t-il ?&quot;">​</a></h3><p>Nicasa a besoin d&#39;accéder à votre système de fichiers pour lire les images et enregistrer les réglages. Aucun accès internet n&#39;est nécessaire pour fonctionner.</p><h2 id="d-autres-questions" tabindex="-1">D&#39;autres questions ? <a class="header-anchor" href="#d-autres-questions" aria-label="Permalink to &quot;D&#39;autres questions ?&quot;">​</a></h2><p>Si vous ne trouvez pas la réponse ici :</p><ol><li>Consultez notre <a href="/fr/">documentation complète</a></li><li>Recherchez dans nos <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">tickets GitHub</a></li><li>Créez un nouveau ticket si nécessaire</li></ol><p>Nous sommes là pour vous aider !</p>',57)])])}const h=a(n,[["render",o]]);export{m as __pageData,h as default};
